ALTER TABLE public.plants ADD COLUMN IF NOT EXISTS category text;
CREATE TABLE public.premium_memberships (user_id uuid PRIMARY KEY, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.premium_memberships TO authenticated;
GRANT ALL ON public.premium_memberships TO service_role;
ALTER TABLE public.premium_memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own membership" ON public.premium_memberships FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.seed_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, seed_name text NOT NULL, quantity text, location text, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.seed_posts TO authenticated;
GRANT ALL ON public.seed_posts TO service_role;
ALTER TABLE public.seed_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Premium read seeds" ON public.seed_posts FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.premium_memberships m WHERE m.user_id = auth.uid() AND m.expires_at > now()));
CREATE POLICY "Premium publish seeds" ON public.seed_posts FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.premium_memberships m WHERE m.user_id = auth.uid() AND m.expires_at > now()));
CREATE POLICY "Delete own seeds" ON public.seed_posts FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.seed_replies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.seed_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.seed_replies TO authenticated;
GRANT ALL ON public.seed_replies TO service_role;
ALTER TABLE public.seed_replies ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Premium read seed replies" ON public.seed_replies FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.seed_posts p WHERE p.id = post_id));
CREATE POLICY "Premium write seed replies" ON public.seed_replies FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.seed_posts p WHERE p.id = post_id));
CREATE POLICY "Delete own seed replies" ON public.seed_replies FOR DELETE TO authenticated USING (user_id = auth.uid());